begin;
\ir _helpers.psql
select plan(22);
select tests.new_user('movie_owner');
select tests.new_user('movie_guest');
update public.profiles set upload_quota_bytes=1000 where id=tests.uid('movie_owner');
update public.app_config set value='1000' where key='movie_storage_cap_bytes';
select set_config('tests.movie',gen_random_uuid()::text,true);
select set_config('tests.payload',jsonb_build_object('movie_id',current_setting('tests.movie'),'title','Test movie','size_bytes',100,'content_type','video/mp4','duration_sec',20,'width',640,'height',360)::text,true);
select is(public.movie_storage_action(tests.uid('movie_guest'),'reserve',current_setting('tests.payload')::jsonb)->>'code','upload_not_allowed','quota zero cannot reserve');
select is(public.movie_storage_action(tests.uid('movie_owner'),'reserve',current_setting('tests.payload')::jsonb)->>'ok','true','owner reserves storage');
select is(public.movie_storage_action(tests.uid('movie_owner'),'reserve',current_setting('tests.payload')::jsonb)->>'ok','true','repeating reservation is idempotent');
update public.profiles set account_deleting=true where id=tests.uid('movie_owner');
select is(public.movie_storage_action(tests.uid('movie_owner'),'reserve',current_setting('tests.payload')::jsonb)->>'code','upload_not_allowed','account deletion rejects an upload reservation retry');
select is(public.movie_storage_action(tests.uid('movie_owner'),'attach',jsonb_build_object('movie_id',current_setting('tests.movie'),'upload_id','late'))->>'code','upload_not_allowed','account deletion rejects attaching another multipart upload');
update public.profiles set account_deleting=false where id=tests.uid('movie_owner');

select is(public.movie_storage_action(tests.uid('movie_owner'),'reserve',current_setting('tests.payload')::jsonb||jsonb_build_object('movie_id',gen_random_uuid()))->>'code','upload_in_progress','one unfinished upload per owner');
select is(public.movie_storage_action(tests.uid('movie_guest'),'attach',jsonb_build_object('movie_id',current_setting('tests.movie'),'upload_id','wrong'))->>'code','not_found','another owner cannot attach an upload');
select ok(not has_function_privilege('authenticated','public.movie_storage_action(uuid,text,jsonb)','execute'),'clients cannot execute storage transitions');
select ok(not has_column_privilege('authenticated','public.movies','object_key','select'),'storage keys are not readable');
select ok(not has_column_privilege('authenticated','public.movies','upload_id','select'),'multipart identifiers are not readable');
select set_config('tests.claim',(public.movie_storage_action(tests.uid('movie_owner'),'complete',jsonb_build_object('movie_id',current_setting('tests.movie')))->'data')::text,true);
select is(public.movie_storage_action(tests.uid('movie_owner'),'delete',jsonb_build_object('movie_id',current_setting('tests.movie')))->>'code','upload_in_progress','deletion cannot race a leased completion');
select is(public.movie_storage_action(tests.uid('movie_owner'),'ready',jsonb_build_object('movie_id',current_setting('tests.movie'),'lease_token',current_setting('tests.claim')::jsonb->>'lease_token','actual_size',99))->>'code','size_mismatch','actual size must match reservation');
select is(public.movie_storage_action(tests.uid('movie_owner'),'ready',jsonb_build_object('movie_id',current_setting('tests.movie'),'lease_token',current_setting('tests.claim')::jsonb->>'lease_token','actual_size',100))->>'ok','true','verified completion becomes ready');
select set_config('tests.movie_room',(tests.call_as('movie_owner',format('public.create_room(%L,%L,%L,%L,%L)','Secret movie title','upload',current_setting('tests.movie'),'private','host'))->'data'->'room'->>'id'),true);
select is(tests.call_as('movie_guest',format('public.room_preview(%L)',(select slug from public.rooms where id=current_setting('tests.movie_room')::uuid)))->'data'->>'title','Private movie room','a slug alone does not expose the movie title');
select is(tests.call_as('movie_guest',format('public.movie_invitation(%L,%L)',(select slug from public.rooms where id=current_setting('tests.movie_room')::uuid),'wrong'))->>'code','bad_key','movie invitation requires the private key');
select is(tests.call_as('movie_guest',format('public.movie_invitation(%L,%L)',(select slug from public.rooms where id=current_setting('tests.movie_room')::uuid),(select join_key from public.room_secrets where room_id=current_setting('tests.movie_room')::uuid)))->'data'->>'title','Test movie','a valid invitation reveals the movie title');
select tests.as_user('movie_guest');
select is((select count(*)::integer from public.movie_library),0,'another owner cannot read the library');
select tests.as_owner();
select set_config('tests.claim',(public.movie_storage_action(tests.uid('movie_owner'),'delete',jsonb_build_object('movie_id',current_setting('tests.movie')))->'data')::text,true);
select is((select content_ref from public.rooms where id=current_setting('tests.movie_room')::uuid),null,'deletion clears the movie from rooms');
select is((select size_bytes::integer from public.movies where id=current_setting('tests.movie')::uuid),100,'deleting retains its reservation');
select is(public.movie_storage_action(tests.uid('movie_owner'),'cleaned',jsonb_build_object('movie_id',current_setting('tests.movie'),'lease_token',current_setting('tests.claim')::jsonb->>'lease_token'))->>'ok','true','cleanup confirmation releases reservation');
select is(public.movie_storage_action(tests.uid('movie_owner'),'delete',jsonb_build_object('movie_id',current_setting('tests.movie')))->>'ok','true','cleanup retry is idempotent');
select is(public.poster_movie_id('------------------------------------/------------------------------------.jpg'),null,'malformed poster names are refused without raising');
select * from finish();
rollback;
